// Bookballz backend (Cloudflare Pages advanced mode): API routes + site fallback.
// Env vars needed: SUPABASE_URL, SUPABASE_SERVICE_KEY (secret).
// Telegram and email keys are saved from the Admin panel (Telegram / Email tabs).
const ADMIN_EMAIL = 'oprahhonourbui@gmail.com';
const json = (o, s = 200) => new Response(JSON.stringify(o), { status: s, headers: { 'content-type': 'application/json' } });
const h = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const sbH = (env) => {
  const k = env.SUPABASE_SERVICE_KEY;
  return k.startsWith('sb_secret_') ? { apikey: k } : { apikey: k, Authorization: 'Bearer ' + k };
};

async function isAdmin(request, env) {
  const auth = request.headers.get('Authorization') || '';
  if (!auth.startsWith('Bearer ')) return false;
  const r = await fetch(`${env.SUPABASE_URL}/auth/v1/user`, { headers: { apikey: env.SUPABASE_SERVICE_KEY, Authorization: auth } });
  if (!r.ok) return false;
  const u = await r.json();
  return String(u.email || '').toLowerCase() === ADMIN_EMAIL;
}

async function secrets(env) {
  const r = await fetch(`${env.SUPABASE_URL}/rest/v1/app_secrets?select=key,value`, { headers: sbH(env) });
  const rows = r.ok ? await r.json() : [];
  return Object.fromEntries(rows.map((x) => [x.key, x.value]));
}
async function setting(env, key) {
  const r = await fetch(`${env.SUPABASE_URL}/rest/v1/settings?key=eq.${key}&select=value`, { headers: sbH(env) });
  return r.ok ? (await r.json())[0]?.value : '';
}

async function tgSend(env, text) {
  const m = await secrets(env);
  const token = m.tg_token || env.TELEGRAM_BOT_TOKEN, chat = m.tg_chat || env.TELEGRAM_CHAT_ID;
  if (!token || !chat) return { ok: false, error: 'Telegram is not set up yet. Save your bot token and chat ID first.' };
  const r = await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
    method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ chat_id: chat, text }),
  });
  const d = await r.json();
  return d.ok ? { ok: true } : { ok: false, error: d.description || 'Telegram rejected the message.' };
}

async function mailSend(env, to, subject, html) {
  const m = await secrets(env);
  if (!m.resend_key || !m.mail_from) return { ok: false, error: 'Email is not set up yet. Add your Resend key and From address in Admin > Email.' };
  const r = await fetch('https://api.resend.com/emails', {
    method: 'POST',
    headers: { Authorization: 'Bearer ' + m.resend_key, 'content-type': 'application/json' },
    body: JSON.stringify({ from: m.mail_from, to: [to], subject, html }),
  });
  const d = await r.json().catch(() => ({}));
  return r.ok ? { ok: true } : { ok: false, error: d.message || 'The email provider rejected the message.' };
}

async function handleOrder({ request, env }) {
  const { ref, email } = await request.json();
  const H = sbH(env);
  const r = await fetch(
    `${env.SUPABASE_URL}/rest/v1/orders?ref=eq.${encodeURIComponent(ref)}&select=status,email,amount,created_at,books(title,pdf_path)`,
    { headers: H }
  );
  const o = (await r.json())[0];
  if (!o || o.email !== String(email || '').trim().toLowerCase()) return json({ status: 'notfound' });
  let status = o.status;
  if (status === 'pending' && Date.now() - new Date(o.created_at) > 24 * 3600e3) status = 'expired';
  const out = { status, title: o.books?.title, amount: o.amount };
  if (status === 'confirmed' && o.books?.pdf_path) {
    const s = await fetch(`${env.SUPABASE_URL}/storage/v1/object/sign/pdfs/${o.books.pdf_path}`, {
      method: 'POST', headers: { ...H, 'content-type': 'application/json' }, body: JSON.stringify({ expiresIn: 300 }),
    });
    const { signedURL } = await s.json();
    if (signedURL) out.url = `${env.SUPABASE_URL}/storage/v1${signedURL}`;
  }
  return json(out);
}

async function handleNotify({ request, env }) {
  const { ref, email } = await request.json();
  const r = await fetch(
    `${env.SUPABASE_URL}/rest/v1/orders?ref=eq.${encodeURIComponent(ref)}&select=status,name,email,phone,amount,receipt_path,books(title)`,
    { headers: sbH(env) }
  );
  const o = (await r.json())[0];
  if (!o || o.email !== String(email || '').trim().toLowerCase() || o.status !== 'awaiting_confirmation') return json({}, 400);
  return json(await tgSend(env, `💸 Bookballz payment claimed\nRef: ${ref}\nBook: ${o.books?.title}\nAmount: ₦${o.amount}\nName: ${o.name}\nPhone: ${o.phone}${o.receipt_path ? '\nReceipt: uploaded (see Admin > Orders)' : ''}\nCheck your bank app, then confirm in admin.`));
}

async function handleTgTest({ request, env }) {
  if (!(await isAdmin(request, env))) return json({ ok: false, error: 'Not allowed. Log in again.' }, 403);
  return json(await tgSend(env, '✅ Bookballz is connected. You will get an alert here when a customer says they have paid.'));
}

async function handleTgFind({ request, env }) {
  if (!(await isAdmin(request, env))) return json({ error: 'Not allowed. Log in again.' }, 403);
  const { token } = await request.json().catch(() => ({}));
  const t = token || (await secrets(env)).tg_token;
  if (!t) return json({ error: 'Paste your bot token first.' });
  const d = await (await fetch(`https://api.telegram.org/bot${t}/getUpdates`)).json();
  if (!d.ok) return json({ error: d.description || 'That bot token is not valid.' });
  const m = [...d.result].reverse().map((u) => u.message || u.channel_post || u.my_chat_member).find((x) => x && x.chat);
  if (!m) return json({ error: 'No messages yet. Open your bot in Telegram, send it "hi", then press this again.' });
  return json({ chat_id: String(m.chat.id), name: m.chat.first_name || m.chat.title || m.chat.username || 'you' });
}

async function handleEmailOrder({ request, env }) {
  if (!(await isAdmin(request, env))) return json({ ok: false, error: 'Not allowed. Log in again.' }, 403);
  const { id } = await request.json();
  const r = await fetch(`${env.SUPABASE_URL}/rest/v1/orders?id=eq.${encodeURIComponent(id)}&select=ref,email,name,status,books(title)`, { headers: sbH(env) });
  const o = (await r.json())[0];
  if (!o || o.status !== 'confirmed') return json({ ok: false, error: 'Order is not confirmed.' });
  const site = (await setting(env, 'site_name')) || 'Bookballz';
  const link = `${new URL(request.url).origin}/#/order/${o.ref}`;
  const html = `<div style="font-family:Arial,sans-serif;max-width:520px"><h2>Your book is ready</h2><p>Hi ${h(o.name)}, your payment for <b>${h(o.books?.title)}</b> is confirmed.</p>
    <p><a href="${h(link)}" style="background:#ff9900;color:#111;padding:12px 22px;border-radius:99px;text-decoration:none;font-weight:bold">Open your download page</a></p>
    <p>If asked, enter this email address: <b>${h(o.email)}</b><br>Order reference: <b>${h(o.ref)}</b></p><p style="color:#666">${h(site)}</p></div>`;
  return json(await mailSend(env, o.email, `Your ${o.books?.title} download is ready`, html));
}

async function handleEmailTest({ request, env }) {
  if (!(await isAdmin(request, env))) return json({ ok: false, error: 'Not allowed. Log in again.' }, 403);
  return json(await mailSend(env, ADMIN_EMAIL, 'Bookballz email test', '<p>Email delivery is working. Buyers will get their download link when you confirm an order.</p>'));
}

// Share page: gives WhatsApp/X/Facebook a title, description and cover image, then sends people to the book.
async function ogPage(url, env, id) {
  const r = await fetch(`${env.SUPABASE_URL}/rest/v1/books?id=eq.${id}&published=eq.true&select=title,subtitle,description,cover_url`, { headers: sbH(env) });
  const b = r.ok ? (await r.json())[0] : null;
  const site = (await setting(env, 'site_name')) || 'Bookballz';
  const dest = `${url.origin}/#/book/${id}`;
  const t = b ? `${b.title} | ${site}` : site;
  const d = b ? String(b.subtitle || b.description || '').slice(0, 200) : '';
  const html = `<!doctype html><meta charset="utf-8"><title>${h(t)}</title><meta property="og:type" content="website"><meta property="og:title" content="${h(t)}"><meta property="og:description" content="${h(d)}">${b?.cover_url ? `<meta property="og:image" content="${h(b.cover_url)}">` : ''}<meta name="twitter:card" content="summary_large_image"><meta http-equiv="refresh" content="0;url=${h(dest)}"><script>location.replace(${JSON.stringify(dest)})</script><a href="${h(dest)}">Open book</a>`;
  return new Response(html, { headers: { 'content-type': 'text/html;charset=utf-8' } });
}

